// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.barcodeimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.ocr.BoundingBox/** * NOUS — Barcode Data Models (Module 6 v4 — Step 6.4). * * Data structures for barcode/QR scanning, including India-first UPI QR + * Regional QR formats (LATAM Pix/Boleto, SEA PromptPay/DuitNow) per strategy * v4 §"Regional Vision Packs". * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.4: BarcodeScannerEngine + UpiQrHandler</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. BARCODE RESULT// ═══════════════════════════════════════════════════════════════════════════/** * One barcode/QR detected in an image. * * @param format the barcode format (QR, Code-128, EAN-13, etc.). * @param rawValue the raw decoded value. * @param boundingBox normalized bounding box (0.0-1.0). * @param confidence detection confidence (0.0-1.0). * @param payloadType parsed payload type (URL, vCard, UPI, WiFi, etc.). * @param parsedPayload structured payload (null if type is UNKNOWN or TEXT). */data class BarcodeResult(    val format: BarcodeFormat,    val rawValue: String,    val boundingBox: BoundingBox,    val confidence: Float,    val payloadType: QrPayloadType = QrPayloadType.UNKNOWN,    val parsedPayload: QrPayload? = null,) {    /** True if this is a QR code. */    val isQrCode: Boolean get() = format == BarcodeFormat.QR_CODE    /** True if the payload was successfully parsed. */    val isPayloadParsed: Boolean get() = parsedPayload != null && payloadType != QrPayloadType.UNKNOWN}/** All barcodes detected in an image. */data class BarcodeScanResult(    val barcodes: List<BarcodeResult>,    val processingTimeMs: Long,) {    /** Number of barcodes detected. */    val barcodeCount: Int get() = barcodes.size    /** True if any barcodes detected. */    val hasBarcodes: Boolean get() = barcodes.isNotEmpty()    /** Get the first QR code, or null. */    val firstQrCode: BarcodeResult?        get() = barcodes.firstOrNull { it.isQrCode }    /** Get all UPI QR codes (India-first). */    val upiQrCodes: List<BarcodeResult>        get() = barcodes.filter { it.payloadType == QrPayloadType.UPI }}/** Tiered barcode scan result. */typealias TieredBarcodeResult = ConfidenceTieredResult<BarcodeScanResult>/** Build a tiered result (confidence = max barcode confidence). */fun tieredBarcodeResult(result: BarcodeScanResult): TieredBarcodeResult {    val maxConfidence = result.barcodes.maxOfOrNull { it.confidence } ?: 0f    return ConfidenceTieredResult.from(result, maxConfidence)}// ═══════════════════════════════════════════════════════════════════════════// 2. BARCODE FORMATS// ═══════════════════════════════════════════════════════════════════════════/** Supported barcode formats (via ML Kit). */enum class BarcodeFormat(val displayName: String) {    QR_CODE("QR Code"),    DATA_MATRIX("Data Matrix"),    PDF_417("PDF-417"),    AZTEC("Aztec"),    CODE_128("Code-128"),    CODE_39("Code-39"),    CODE_93("Code-93"),    CODABAR("Codabar"),    EAN_13("EAN-13"),    EAN_8("EAN-8"),    ITF("ITF"),    UPC_A("UPC-A"),    UPC_E("UPC-E"),    UNKNOWN("Unknown"),}// ═══════════════════════════════════════════════════════════════════════════// 3. QR PAYLOAD TYPES// ═══════════════════════════════════════════════════════════════════════════/** Types of QR payloads (parsed by [QrPayloadParser]). */enum class QrPayloadType(val displayName: String) {    URL("URL"),    VCARD("Contact (vCard)"),    WIFI("WiFi Network"),    UPI("UPI Payment (India)"),    PIX("Pix Payment (Brazil)"),    BOLETO("Boleto Payment (Brazil)"),    PROMPTPAY("PromptPay Payment (Thailand)"),    DUITNOW("DuitNow Payment (Malaysia)"),    SMS("SMS"),    EMAIL("Email"),    PHONE("Phone Number"),    GEO("Geographic Location"),    CALENDAR_EVENT("Calendar Event"),    DRIVER_LICENSE("Driver License"),    TEXT("Plain Text"),    UNKNOWN("Unknown"),}// ═══════════════════════════════════════════════════════════════════════════// 4. PARSED QR PAYLOADS// ═══════════════════════════════════════════════════════════════════════════/** Sealed hierarchy of parsed QR payloads. */sealed interface QrPayload {    /** URL payload. */    data class UrlPayload(val url: String, val isSecure: Boolean) : QrPayload {        val domain: String get() = try {            java.net.URI(url).host ?: url        } catch (t: Throwable) {            url        }    }    /** vCard (contact) payload. */    data class VCardPayload(        val name: String?,        val phoneNumbers: List<String>,        val emails: List<String>,        val organization: String?,        val title: String?,        val url: String?,        val address: String?,    ) : QrPayload    /** WiFi network payload. */    data class WifiPayload(        val ssid: String,        val password: String?,        val encryptionType: WifiEncryptionType,    ) : QrPayload    /** UPI payment payload (India-first). */    data class UpiPayload(        val upiId: String,           // "name@bank"        val payeeName: String?,      // "Roshan Kumar"        val amount: Double?,         // 100.00 (optional)        val currency: String,        // "INR"        val note: String?,           // "Lunch"        val merchantCode: String?,   // "0000" (optional)    ) : QrPayload {        val isValidUpiId: Boolean            get() = upiId.contains("@") && upiId.length in 5..100    }    /** Pix payment payload (Brazil — LATAM Regional Pack). */    data class PixPayload(        val pixKey: String,        val payeeName: String?,        val amount: Double?,        val currency: String,  // "BRL"    ) : QrPayload    /** Boleto payment payload (Brazil). */    data class BoletoPayload(        val barcode: String,        val amount: Double?,        val dueDate: String?,    ) : QrPayload    /** PromptPay payload (Thailand — SEA Regional Pack). */    data class PromptPayPayload(        val promptPayId: String,  // National ID or phone number        val payeeName: String?,        val amount: Double?,        val currency: String,  // "THB"    ) : QrPayload    /** DuitNow payload (Malaysia — SEA Regional Pack). */    data class DuitNowPayload(        val duitNowId: String,        val payeeName: String?,        val amount: Double?,        val currency: String,  // "MYR"    ) : QrPayload    /** SMS payload. */    data class SmsPayload(val phoneNumber: String, val message: String?) : QrPayload    /** Email payload. */    data class EmailPayload(val email: String, val subject: String?, val body: String?) : QrPayload    /** Phone payload. */    data class PhonePayload(val phoneNumber: String) : QrPayload    /** Geographic location payload. */    data class GeoPayload(val latitude: Double, val longitude: Double, val query: String?) : QrPayload    /** Plain text payload (fallback). */    data class TextPayload(val text: String) : QrPayload}/** WiFi encryption types. */enum class WifiEncryptionType(val displayName: String) {    WPA("WPA/WPA2"),    WEP("WEP"),    NONE("Open (No Password)"),    UNKNOWN("Unknown"),}// ═══════════════════════════════════════════════════════════════════════════// 5. REGIONAL QR FORMATS// ═══════════════════════════════════════════════════════════════════════════/** * Regional QR format configuration (per strategy v4 §"Regional Vision Packs"). * * Drives which payment QR formats the [UpiQrHandler] recognizes. */enum class RegionalQrFormat(val displayName: String, val supportedPayloadTypes: Set<QrPayloadType>) {    /** India (default) — UPI + BharatQR. */    INDIA("India", setOf(QrPayloadType.UPI, QrPayloadType.URL, QrPayloadType.VCARD, QrPayloadType.WIFI)),    /** LATAM — Pix (Brazil) + Boleto. */    LATAM("LATAM", setOf(QrPayloadType.PIX, QrPayloadType.BOLETO, QrPayloadType.URL, QrPayloadType.VCARD, QrPayloadType.WIFI)),    /** SEA — PromptPay (Thailand) + DuitNow (Malaysia). */    SEA("SEA", setOf(QrPayloadType.PROMPTPAY, QrPayloadType.DUITNOW, QrPayloadType.URL, QrPayloadType.VCARD, QrPayloadType.WIFI)),    /** All regions (for testing). */    ALL("All", QrPayloadType.entries.toSet());    /** True if this region supports a given payload type. */    fun supports(type: QrPayloadType): Boolean = type in supportedPayloadTypes    companion object {        /** Get the default region for a country code (ISO 3166-1 alpha-2). */        fun forCountryCode(countryCode: String): RegionalQrFormat = when (countryCode.uppercase()) {            "IN" -> INDIA            "BR", "AR", "MX", "CO", "CL", "PE" -> LATAM            "TH", "MY", "SG", "ID", "VN", "PH" -> SEA            else -> INDIA  // Default to India        }    }}